// Level "Canvas": 8 × 8 cells of 10 mm inside the frame.
// Pen down when Me and It are in the same cell; it stays down until they are more
// than 1.5 cells apart, so a small drift of one hand does not break the line.

const N = 8, CELL = 10, X0 = 140, Y0 = 63;
const PEN_UP_DISTANCE = 1.5 * CELL;
const COLORS = {
  red:   { fill: "#e63946", tone: 330 },
  green: { fill: "#2a9d4b", tone: 523 },
  blue:  { fill: "#2f6fdf", tone: 784 },
};

const pixels = new Array(N * N).fill(null); // colour name per cell, null = empty
const marks = new Array(N * N).fill(null);  // the coloured square in the preview
let color = "red";
let erasing = false;
let penDown = false;


/** Cell index under a point, or -1 outside the canvas. */
function cellAt(p) {
  const col = Math.floor((p.x - X0) / CELL), row = Math.floor((p.y - Y0) / CELL);
  return col >= 0 && col < N && row >= 0 && row < N ? row * N + col : -1;
}

function setPixel(i, value) {
  if (i < 0 || pixels[i] === value) return;
  pixels[i] = value;
  marks[i]?.remove();
  marks[i] = null;
  if (value) {
    const x = X0 + ((i % N) + 0.5) * CELL, y = Y0 + (Math.floor(i / N) + 0.5) * CELL;
    marks[i] = panto.entity({ x, y, r: CELL / 2, color: COLORS[value].fill });
    sound.beep(COLORS[value].tone, 70, { volume: 0.15 });
  } else {
    sound.tick();
  }
}

async function chirp(from, to) {
  await sound.beep(from, 50, { volume: 0.15 });
  sound.beep(to, 70, { volume: 0.15 });
}

function updatePen() {
  const meCell = cellAt(me.position);
  if (!penDown && meCell >= 0 && meCell === cellAt(it.position)) {
    penDown = true;
    chirp(500, 800);
  } else if (penDown && (meCell < 0 || distance(me, it) > PEN_UP_DISTANCE)) {
    penDown = false;
    chirp(800, 500);
  }
  if (penDown) setPixel(meCell, erasing ? null : color);
}

// Extract every boundary loop from the painted grid, including holes.
let recognitionRails=[];
function paintedContours(){
  const edges=[];
  const add=(x1,y1,x2,y2)=>edges.push({x1,y1,x2,y2,used:false,dir:direction(x2-x1,y2-y1)});
  function direction(dx,dy){return dx>0?0:dy>0?1:dx<0?2:3;}
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){
    if(pixels[y*N+x]===null)continue;
    if(y===0||pixels[(y-1)*N+x]===null)add(x,y,x+1,y);
    if(x===N-1||pixels[y*N+x+1]===null)add(x+1,y,x+1,y+1);
    if(y===N-1||pixels[(y+1)*N+x]===null)add(x+1,y+1,x,y+1);
    if(x===0||pixels[y*N+x-1]===null)add(x,y+1,x,y);
  }
  const key=(x,y)=>`${x},${y}`,outgoing=new Map();
  edges.forEach((edge,i)=>{const k=key(edge.x1,edge.y1);if(!outgoing.has(k))outgoing.set(k,[]);outgoing.get(k).push(i);});
  const loops=[];
  for(let start=0;start<edges.length;start++){
    if(edges[start].used)continue;
    const first=edges[start],points=[{x:first.x1,y:first.y1}];let index=start,closed=false;
    for(let guard=0;guard<=edges.length;guard++){
      const edge=edges[index];if(edge.used)break;edge.used=true;
      points.push({x:edge.x2,y:edge.y2});
      if(edge.x2===first.x1&&edge.y2===first.y1){closed=true;break;}
      const candidates=(outgoing.get(key(edge.x2,edge.y2))||[]).filter(i=>!edges[i].used);
      if(!candidates.length)break;
      // Keep painted cells on the same side at diagonal corner junctions.
      candidates.sort((a,b)=>turnRank((edges[a].dir-edge.dir+4)%4)-turnRank((edges[b].dir-edge.dir+4)%4));
      index=candidates[0];
    }
    if(closed&&points.length>=5)loops.push(simplifyContour(points));
  }
