function simplifyContour(closedPoints){
  const points=closedPoints.slice(0,-1),corners=[];
  for(let i=0;i<points.length;i++){
    const prev=points[(i+points.length-1)%points.length],cur=points[i],next=points[(i+1)%points.length];
    const dx1=cur.x-prev.x,dy1=cur.y-prev.y,dx2=next.x-cur.x,dy2=next.y-cur.y;
