  recognitionRails.forEach(rail=>rail.remove());recognitionRails=[];
  contours.forEach((points,i)=>recognitionRails.push(panto.rail(points,{strength:2,handles:'me',name:`Contour ${i+1}`})));
  speak(`${contours.length} contours traced with rails.`,{interrupt:true});
